/**
 * The single source of asset names and paths. Code refers to assets through ASSET.*
 * (or typed AssetKey strings in level data). assetMeta.json is generated by `npm run assets`.
 */
import meta from './assetMeta.json';

export type AssetKey = keyof typeof meta;

export interface Rect {
  x: number;
  y: number;
  w: number;
  h: number;
}

export interface AssetInfo {
  folder: string;
  /** Canvas size of the processed PNG. */
  w: number;
  h: number;
  /** Visible content inside the canvas. */
  content: Rect;
}

const META = meta as Record<AssetKey, AssetInfo>;

