/** Loaded by BootScene so the preloader can draw its progress bar. */
export const BOOT_ASSETS: readonly AssetKey[] = [ASSET.progressFrame, ASSET.progressFill, ASSET.bgMenu];

export function isAssetKey(key: string): key is AssetKey {
  return key in META;
}

export function assetInfo(key: AssetKey): AssetInfo {
  return META[key];
}

/** Relative URL (works from file:// inside Capacitor). */
export function assetUrl(key: AssetKey): string {
  return `assets/${META[key].folder}/${key}.png`;
}

/** Everything Phase 1 loads (the magician rig is reserved for Phase 2). */
export function phase1Assets(): AssetKey[] {
  return (Object.keys(META) as AssetKey[]).filter((k) => META[k].folder !== 'magician');
}
